const app=document.getElementById('app'), menu=document.getElementById('globalMenu');
function avatar(){return `<img src="${A}001.png" width="20" height="20">`}
function headerName(n){document.getElementById('pageBrand').textContent=n}
function renderDashboard(){
 headerName('Dashboard');
 app.innerHTML=`<div class="dashboard">
  <aside class="sidebar"><button class="newbtn btn" id="sideNew">＋ New</button><div class="side-title">Top repositories</div>
  <input class="repo-search" placeholder="Find a repository..."><div class="repo-line">${avatar()} Jimmy6668889/jack</div></aside>
  <section class="mainhome"><div>
   <h1>Home</h1><div class="copilot">Ask Copilot <span class="send">▷</span></div>
   <div class="chips"><button class="chip btn"><span>◉</span>Interpret an architecture diagram</button><button class="chip btn"><span>♧</span>Summarize a pull request</button><button class="chip btn"><span style="color:#1a7f37">◉</span>Suggest next steps for an issue</button></div>
   <div class="feed-head">Feed <button class="filter btn">☷ &nbsp;Filter</button></div>
   <div class="feed"><div class="trend">⌁ &nbsp; Trending repositories · <a>See more</a><span class="dots">···</span></div>
    <div class="repo-card"><button class="star btn">☆ Star　⌄</button><div class="repo-name">${avatar()} winapps-org/winapps</div><div class="repo-desc">Run Windows apps such as Microsoft Office/Adobe in Linux (Ubuntu/Fedora) and GNOME/KDE as if they were a part of the native OS, including Nautilus integration. Hard fork of https://github.com/Fmst...</div><div class="meta"><span class="green-dot"></span>Shell　☆ 6.3k</div></div>
