  <div class="footer">◉　© 2025 GitHub, Inc.　 <span>Terms</span><span>Privacy</span><span>Security</span><span>Status</span><span>Docs</span><span>Contact</span><span>Manage cookies</span><span>Do not share my personal information</span></div>
 </section></div>`;
 document.getElementById('sideNew').onclick=showCreate;
 document.getElementById('newRepoMenu').onclick=showCreate;
}
function showCreate(){state.page='create';menu.style.display='none';renderCreate()}
function renderCreate(){
 headerName('New repository');
 app.innerHTML=`<div class="create-page"><div class="create-wrap">
 <div class="create-title">Create a new repository <span class="preview">Preview</span><a class="classic">Switch back to classic experience</a></div>
 <div class="subtext">Repositories contain a project's files and version history. Have a project elsewhere? <u>Import a repository</u>.<br><i>Required fields are marked with an asterisk (*).</i></div>
 <div class="step"><span class="stepnum">1</span><div class="section-title">General</div>
  <div class="row"><div class="owner"><label class="form-label">Owner *</label><div class="owner-select">${avatar()}Jimmy6668889⌄</div></div><div class="slash">/</div><div class="repo-input"><label class="form-label">Repository name *</label><input id="repoName" class="control" value="${state.name}"><div id="available" class="available" style="display:${state.name?'block':'none'}">● ${state.name||'jackccc'} is available.</div></div></div>
  <div class="hint">Great repository names are short and memorable. How about <a>sturdy-waffle?</a></div>
  <label class="form-label">Description</label><input id="desc" class="control" value="${state.desc}"><div class="subtext" id="counter">${state.desc.length} / 350 characters</div>
 </div>
 <div class="step"><span class="stepnum">2</span><div class="section-title">Configuration</div><div class="config-box">
  <div class="config-row"><div class="config-copy"><strong>Choose visibility *</strong><small>Choose who can see and commit to this repository</small></div><div style="position:relative"><button class="select-btn btn" id="visibility">${state.visibility==='Private'?'♙ Private':'▣ Public'}　⌄</button>${state.visOpen?`<div class="menu-pop visibility-pop"><div class="visibility-option btn" data-vis="Public">✓　▣ <b>Public</b><small>Anyone on the internet can see this repository.</small></div><div class="visibility-option btn" data-vis="Private">♙　<b>Private</b><small>You choose who can see and commit to this repository.</small></div></div>`:''}</div></div>
  <div class="config-row"><div class="config-copy"><strong>Add README</strong><small>READMEs can be used as longer descriptions. <u>About READMEs</u></small></div><span style="margin-right:8px"> ${state.readme?'On':'Off'} </span><button id="readme" class="toggle btn ${state.readme?'on':''}"><i></i></button></div>
  <div class="config-row"><div class="config-copy"><strong>Add .gitignore</strong><small>.gitignore tells git which files not to track. <u>About ignoring files</u></small></div><button class="select-btn btn">No .gitignore　⌄</button></div>
  <div class="config-row"><div class="config-copy"><strong>Add license</strong><small>Licenses explain how others can use your code. <u>About licenses</u></small></div><div style="position:relative"><button class="select-btn btn" id="license">${state.license==='No license'?'No license':'⚖ '+state.license}　⌄</button>${state.licOpen?`<div class="menu-pop license-pop"><b>Choose a license</b><input class="license-search" placeholder="⌕ Search licenses"><div class="license-list">${['No license','Apache License 2.0','GNU General Public License v3.0','MIT License','BSD 2-Clause "Simplified" License','BSD 3-Clause "New" or "Revised" License','Boost Software License 1.0','Creative Commons Zero v1.0 Universal','Eclipse Public License 2.0','GNU Affero General Public License v3.0'].map(x=>`<div class="license-item btn ${x===state.license?'active-choice':''}" data-license="${x}">${x===state.license?'✓　':''}${x}</div>`).join('')}</div></div>`:''}</div></div>
 </div><button class="create-btn btn" id="createRepo">Create repository</button></div></div></div>`;
 bindCreate();
}
function bindCreate(){
 const n=document.getElementById('repoName'),d=document.getElementById('desc');
 n.oninput=()=>{state.name=n.value;document.getElementById('available').style.display=n.value?'block':'none';document.getElementById('available').textContent='● '+n.value+' is available.'};
 d.oninput=()=>{state.desc=d.value;document.getElementById('counter').textContent=d.value.length+' / 350 characters'};
 document.getElementById('visibility').onclick=()=>{state.visOpen=!state.visOpen;state.licOpen=false;renderCreate()};
 document.querySelectorAll('[data-vis]').forEach(x=>x.onclick=()=>{state.visibility=x.dataset.vis;state.visOpen=false;renderCreate()});
 document.getElementById('readme').onclick=()=>{state.readme=!state.readme;renderCreate()};
 document.getElementById('license').onclick=()=>{state.licOpen=!state.licOpen;state.visOpen=false;renderCreate()};
 document.querySelectorAll('[data-license]').forEach(x=>x.onclick=()=>{state.license=x.dataset.license;state.licOpen=false;renderCreate()});
 document.getElementById('createRepo').onclick=renderRepo;
}
function renderRepo(){
 headerName('jackccc');
 app.innerHTML=`<div class="repo-page"><nav class="repo-nav"><span class="selected">⌁ Code</span><span>◉ Issues</span><span>♧ Pull requests</span><span>◷ Actions</span><span>▣ Projects</span><span>♢ Security</span><span>⌁ Insights</span><span>⚙ Settings</span></nav>
 <div class="repo-content"><div class="repo-top"><h2>${avatar()} jackccc</h2><span class="private">Private</span><div class="repo-actions"><button class="small-btn btn">◉ Watch　⌄</button><button class="small-btn btn">♧ Fork　0　⌄</button><button class="small-btn btn">☆ Star　0　⌄</button></div></div>
