 <div class="filebox"><div class="commit">${avatar()}<b>Jimmy6668889</b>　Initial commit <span style="margin-left:auto">31b2bf4 · now　 ◷ 1 Commit</span></div><div class="file">▱　LICENSE <span class="msg">Initial commit　　now</span></div><div class="file">▱　README.md <span class="msg">Initial commit　　now</span></div></div>
 <div class="readme"><div class="readme-head">▣ README　　　　　⚖ Apache-2.0 license</div><h1>jackccc</h1><p>${state.desc||'an interesting boy'}</p></div></section>
 <aside class="about"><h3>About　⚙</h3><p>${state.desc||'an interesting boy'}</p><div class="about-item">▣　Readme</div><div class="about-item">⌁　Activity</div><div class="about-item">☆　0 stars</div><div class="about-item">◉　0 watching</div><div class="about-item">♧　0 forks</div><hr><h3>Releases</h3><p>No releases published<br><a>Create a new release</a></p><hr><h3>Packages</h3><p>No packages published<br><a>Publish your first package</a></p></aside>
 <div class="repo-footer">◉　© 2025 GitHub, Inc.　 Terms　 Privacy　 Security　 Status　 Docs　 Contact　 Manage cookies　 Do not share my personal information</div></div></div>`;
}
document.getElementById('globalPlus').onclick=()=>menu.style.display=menu.style.display==='none'?'block':'none';
renderDashboard();
</script>
</body>
